// Task: 实现游戏结果模型，记录游戏结束状态和统计信息

import 'package:equatable/equatable.dart';
import 'piece_type.dart';

/// 游戏状态
enum GameStatus {
  /// 游戏进行中
  ongoing,

  /// 黑方胜利
  blackWin,

  /// 白方胜利
  whiteWin,

  /// 平局
  draw,

  /// 超时
  timeout,

  /// 弃局
  abandoned,
}

/// 机器可读的终局原因；界面文案不得作为规则或协议判断依据。
enum GameEndReason {
  pieceCount,
  noLegalMoves,
  noCaptureLimit,
  timeout,
  disconnect,
  abandoned,
}

extension GameStatusExtension on GameStatus {
  /// 游戏是否结束
  bool get isGameOver {
    return this != GameStatus.ongoing;
  }

  /// 获取显示文本
  String getDisplayText() {
    switch (this) {
      case GameStatus.ongoing:
        return '进行中';
      case GameStatus.blackWin:
        return '黑方胜利';
      case GameStatus.whiteWin:
        return '白方胜利';
      case GameStatus.draw:
        return '平局';
      case GameStatus.timeout:
        return '超时';
      case GameStatus.abandoned:
        return '弃局';
    }
  }
}

/// 游戏结果
///
/// 记录游戏结束时的完整信息，包括：
/// - 游戏状态
/// - 胜者
/// - 胜负原因
/// - 总步数
/// - 对局时长
class GameResult extends Equatable {
  /// 游戏状态
  final GameStatus status;

  /// 胜者（可能为null，如弃局）
  final PieceType? winner;

  /// 胜负原因
  final String reason;

  /// 机器可读的终局原因。
  final GameEndReason endReason;

  /// 总步数
  final int moveCount;

  /// 对局时长
  final Duration duration;

  const GameResult({
    required this.status,
    this.winner,
    required this.reason,
    this.endReason = GameEndReason.pieceCount,
    required this.moveCount,
    required this.duration,
  });

  /// 创建黑方胜利结果
  factory GameResult.blackWin({
    required String reason,
    GameEndReason endReason = GameEndReason.pieceCount,
    required int moveCount,
    required Duration duration,
  }) {
    return GameResult(
      status: GameStatus.blackWin,
      winner: PieceType.black,
      reason: reason,
      endReason: endReason,
      moveCount: moveCount,
      duration: duration,
    );
  }

  /// 创建白方胜利结果
  factory GameResult.whiteWin({
    required String reason,
    GameEndReason endReason = GameEndReason.pieceCount,
    required int moveCount,
    required Duration duration,
  }) {
    return GameResult(
      status: GameStatus.whiteWin,
      winner: PieceType.white,
      reason: reason,
      endReason: endReason,
      moveCount: moveCount,
      duration: duration,
    );
  }

  /// 创建平局结果
  factory GameResult.draw({
    required String reason,
    GameEndReason endReason = GameEndReason.noCaptureLimit,
    required int moveCount,
    required Duration duration,
  }) {
    return GameResult(
      status: GameStatus.draw,
      winner: null,
      reason: reason,
      endReason: endReason,
      moveCount: moveCount,
      duration: duration,
    );
  }

  /// 创建超时结果
  factory GameResult.timeout({
    required PieceType timeoutPlayer,
    required int moveCount,
    required Duration duration,
  }) {
    return GameResult(
      status: GameStatus.timeout,
      winner: timeoutPlayer.getOpponent(),
      reason: '${timeoutPlayer.getDisplayName()}超时',
      endReason: GameEndReason.timeout,
      moveCount: moveCount,
      duration: duration,
    );
  }

  /// 创建弃局结果
  factory GameResult.abandoned({
    required PieceType abandonedPlayer,
    required int moveCount,
    required Duration duration,
  }) {
    return GameResult(
      status: GameStatus.abandoned,
      winner: abandonedPlayer.getOpponent(),
      reason: '${abandonedPlayer.getDisplayName()}认输',
      endReason: GameEndReason.abandoned,
      moveCount: moveCount,
      duration: duration,
    );
  }

  /// 游戏是否结束
  bool get isGameOver => status.isGameOver;

  GameResult copyWith({Duration? duration}) {
    return GameResult(
      status: status,
      winner: winner,
      reason: reason,
      endReason: endReason,
      moveCount: moveCount,
      duration: duration ?? this.duration,
    );
  }

  /// 获取结果摘要文本
  String getSummary() {
    final buffer = StringBuffer();
    buffer.writeln(status.getDisplayText());
    if (winner != null) {
      buffer.writeln('获胜方: ${winner!.getDisplayName()}');
    }
    buffer.writeln('原因: $reason');
    buffer.writeln('总步数: $moveCount');
    buffer.writeln('用时: ${_formatDuration(duration)}');
    return buffer.toString();
  }

  /// 格式化时长
  String _formatDuration(Duration duration) {
    final hours = duration.inHours;
    final minutes = duration.inMinutes % 60;
    final seconds = duration.inSeconds % 60;

    if (hours > 0) {
      return '$hours小时$minutes分$seconds秒';
    } else if (minutes > 0) {
      return '$minutes分$seconds秒';
    } else {
      return '$seconds秒';
    }
  }

  /// 转换为Map（用于序列化）
  Map<String, dynamic> toJson() {
    return {
      'status': status.name,
      'winner': winner?.name,
      'reason': reason,
      'endReason': endReason.name,
      'moveCount': moveCount,
      'duration': duration.inMilliseconds,
    };
  }

  /// 从Map创建（用于反序列化）
  factory GameResult.fromJson(Map<String, dynamic> json) {
    return GameResult(
      status: GameStatus.values.firstWhere(
        (e) => e.name == json['status'],
      ),
      winner: json['winner'] != null
          ? PieceType.values.firstWhere(
              (e) => e.name == json['winner'],
            )
          : null,
      reason: json['reason'] as String,
      endReason: json['endReason'] == null
          ? _legacyEndReason(
              GameStatus.values.firstWhere(
                (status) => status.name == json['status'],
              ),
            )
          : GameEndReason.values.firstWhere(
              (reason) => reason.name == json['endReason'],
            ),
      moveCount: json['moveCount'] as int,
      duration: Duration(milliseconds: json['duration'] as int),
    );
  }

  @override
  List<Object?> get props => [
        status,
        winner,
        reason,
        endReason,
        moveCount,
        duration,
      ];

  static GameEndReason _legacyEndReason(GameStatus status) {
    switch (status) {
      case GameStatus.draw:
        return GameEndReason.noCaptureLimit;
      case GameStatus.timeout:
        return GameEndReason.timeout;
      case GameStatus.abandoned:
        return GameEndReason.abandoned;
      case GameStatus.ongoing:
      case GameStatus.blackWin:
      case GameStatus.whiteWin:
        return GameEndReason.pieceCount;
    }
  }

  @override
  String toString() {
    return 'GameResult(status: $status, winner: $winner, '
        'reason: $reason, moves: $moveCount, duration: $duration)';
  }
}
